insert into public.allin_trip_days (trip_slug, day_from, day_to, label, place, body, transport, activities, meals) values
('cambodia',1,1,'Day 1','Phnom Penh','Welcome to Cambodia! Arrive in the capital city of Phnom Penh and make your way to Mad Monkey. Settle in before meeting up with your crew for a Welcome Khmer Family Dinner (6:30 PM – 8:00 PM) to toast to the trip ahead and get to know the team.',null,null,'Welcome Khmer family dinner (plus free-flow drinks)'),
('cambodia',2,2,'Day 2','Phnom Penh','Dive deep into Cambodian history with a morning guided cultural tour of the S21 Prison and the Killing Fields (8:00 AM – 2:00 PM). Afterward, refresh at the hostel before heading out at 4:30 PM for a relaxing sunset boat cruise along the river.',null,'S21 & Killing Fields cultural tour, sunset boat cruise',null),
('cambodia',3,3,'Day 3','Phnom Penh','Spend the day exploring Phnom Penh at your own pace. Check out local markets, wander through the historic streets, or kick back by the pool. In the evening, regroup with the squad for a hostel BBQ and pool party (6:00 PM – 8:00 PM).',null,'Hostel BBQ & pool party',null),
('cambodia',4,4,'Day 4','Phnom Penh → Siem Reap','Board a morning bus at 10:00 AM for a scenic drive north across the Cambodian countryside to Siem Reap, arriving around 6:00 PM. Check into Mad Monkey Siem Reap and roll up your sleeves for a make-your-own pizza night (7:30 PM – 8:30 PM).','Bus transfer from Phnom Penh to Siem Reap','Make your own pizza night',null),
('cambodia',5,5,'Day 5','Siem Reap','Enjoy a relaxed daytime schedule to explore Siem Reap or recharge by the pool. Once night falls, get ready to turn up the energy as the group hits the town for a legendary messy pub crawl starting at 8:00 PM.',null,'Nightly messy pub crawl',null),
('cambodia',6,6,'Day 6','Siem Reap','Head out at 2:00 PM for a floating village tour to experience local life along the waters of Tonle Sap lake. Return to the hostel in the evening for dinner with the group, followed by a lively music quiz and bingo night.',null,'Tonle Sap floating village tour, hostel music quiz & bingo for a cause','Lunch & drink on tour'),
('cambodia',7,7,'Day 7','Siem Reap → Sihanoukville','Set an early alarm for the iconic Angkor Wat sunrise tour (4:30 AM – 12:30 PM). Marvel at the ancient temple complex with a guide before heading back for lunch. Later tonight, board an overnight sleeper bus at 7:30 PM bound for Sihanoukville. Note that the Angkor Wat entry pass is purchased in person with ID.','Overnight VIP sleeper bus to Sihanoukville','Angkor Wat sunrise tour','Tour lunch & drink'),
('cambodia',8,8,'Day 8','Sihanoukville → Koh Rong','Arrive in Sihanoukville at 7:00 AM and board the 8:30 AM fast ferry to Koh Rong Longset Pier. Walk to Mad Monkey, check into your beach dorm, and jump straight into beach olympics (2:30 PM – 4:30 PM). Cool down with a free-flow drink session, then wrap up the night with a beach fireshow at 8:30 PM.','Fast ferry to Koh Rong','Beach olympics, beach fireshow','Free-flow drinks session'),
('cambodia',9,9,'Day 9','Koh Rong','Spend the day soaking up the tropical island life on Koh Rong. Join in on the afternoon volleyball tournament (1:30 PM – 3:00 PM), then regroup in the evening for an island Caribbean dinner feast (6:30 PM – 8:30 PM).',null,'Hostel volleyball tournament','Caribbean dinner'),
('cambodia',10,10,'Day 10','Koh Rong (Nestival)','Warm up for the biggest night of the trip with a bottomless brunch featuring a live DJ set. Spend the afternoon relaxing before heading out to Nestival at 7:00 PM, the ultimate beach and jungle rave that keeps pounding until sunrise.',null,'Bottomless brunch with live DJ, Nestival beach & jungle rave ticket','Bottomless brunch (light bite + free-flow drinks)'),
('cambodia',11,11,'Day 11','Koh Rong','Recovery day! Take it easy on the beach with complimentary kayak and paddleboard rentals (8:00 AM – 5:00 PM). In the evening, dig into a Sunday roast accompanied by a beer tower, then cap off the night with another beach fireshow at 8:30 PM.',null,'Kayak & paddleboard rental, beach fireshow','Sunday roast dinner & beer tower'),
('cambodia',12,12,'Day 12','Koh Rong → Koh Sdach','Take a 1-hour ferry over to the hidden gem island of Koh Sdach. Settle into Mad Monkey Koh Sdach, check out the spa amenities, and join the afternoon wellness challenge. At 4:00 PM, hop on e-bikes for the Koh Sdach Loop to explore the island, enjoy local beers, and watch the sunset.','Ferry transfer to Koh Sdach','Hostel wellness challenge, Koh Sdach e-bike loop',null),
('cambodia',13,13,'Day 13','Koh Sdach','Enjoy a relaxed morning on the island before jumping into an afternoon waterpolo challenge at 2:00 PM. Set sail at 4:00 PM for an island hopping sunset cruise, then wrap up the night back at the hostel with a pub quiz.',null,'Waterpolo challenge, island hopping sunset cruise, hostel pub quiz',null),
('cambodia',14,14,'Day 14','Koh Sdach','Spend a chill morning fishing off the beach with hostel gear. Jump on another relaxing sunset cruise (4:30 PM – 6:30 PM) before heading back to the hostel for a final make-your-own pizza night with your crew.',null,'Beach fishing gear rental, sunset cruise, make your own pizza night',null),
('cambodia',15,15,'Day 15','Koh Sdach → Phnom Penh','Say farewell to your squad! Catch the 9:00 AM transfer bus back to Phnom Penh, arriving around 1:00 PM, to connect with your onward travel.','Transfer bus back to Phnom Penh',null,null),
('indonesia',1,1,'Day 1','Uluwatu','Welcome to Bali! Touch down at Denpasar (DPS) Airport and make your way to Mad Monkey Uluwatu. Settle into your home base before meeting up with your crew for a Welcome Sunset session at Panorama Point. Toast to the start of an epic adventure, get to know your fellow travellers, and kick off the trip with a welcome drink.',null,'Welcome Sunset session at Panorama Point','Welcome drink'),
('indonesia',2,2,'Day 2','Uluwatu','Rise and shine early, very early. Set off on an unforgettable Mt. Batur Sunrise Trek to catch the morning rays breaking over the clouds. After trekking back down, spend the rest of the day in full recovery mode. Hit the Mad Monkey wellness setup to recharge with the sauna, hot tub, and ice bath. Wrap up the evening with the group over a family dinner and drinks.',null,'Mt. Batur Sunrise Trek, Mad Monkey Sauna, Hot Tub & Ice Bath access','Family Dinner (plus 2 free drinks)'),
('indonesia',3,3,'Day 3','Uluwatu → Nusa Lembongan','Say goodbye to Uluwatu as you catch a taxi to Sanur, followed by a fast 30-minute boat ride over to island paradise at Mad Monkey Nusa Lembongan. Once checked in, take advantage of top-tier hostel facilities: take a dip in the luxury pool, sweat it out in the gym or sauna, or test your grit with an ice bath session.','Taxi & fast boat to Nusa Lembongan','Access to Mad Monkey Lembongan pool, gym, sauna & ice baths',null),
('indonesia',4,4,'Day 4','Nusa Lembongan','Head out early for the ultimate bucket-list moment: snorkeling alongside massive manta rays as they glide through the waters off Nusa Penida. Afterwards, head back to dry land for a completely relaxed afternoon, hit the beach, kick back by the pool, or claim a hammock. In the evening, regroup with the crew back at the hostel for a family dinner and a few drinks.',null,'Manta Ray Snorkeling Experience, Family Dinner',null),
('indonesia',5,5,'Day 5','Nusa Lembongan & Nusa Penida','Hop on a boat for a full day of island hopping around the stunning landscapes and dramatic cliffs of Nusa Penida (8:30 AM to 5:00 PM). After taking in the sights, head back to Mad Monkey for Karaoke Night (8:00 PM to 10:00 PM).',null,'Nusa Penida Island Hopping Day Trip, Karaoke Night',null),
('indonesia',6,6,'Day 6','Nusa Lembongan → Gili Trawangan','Catch an early fast boat over to the legendary, motorized-vehicle-free island of Gili Trawangan. Check into Mad Monkey Gili T and get your lay of the land. Tonight, join the family for a traditional Mexican dinner spread and drinks.','Fast boat to Gili Trawangan',null,'Mexican Family Dinner (plus 2 free drinks)'),
('indonesia',7,7,'Day 7','Gili Trawangan','Enjoy a chill morning to relax and explore the island at your own pace. Afterwards, the party comes to you back at Mad Monkey. Get ready for an epic Foam Party featuring a live DJ set.',null,'Mad Monkey Foam Party with live DJ',null),
('indonesia',8,8,'Day 8','Gili Trawangan','Set sail for the iconic Mad Monkey Boat Party (2:00 PM to 6:00 PM). Dance, swim, and soak up the island vibes out on the water. Keep the high energy going into the night back at the hostel with an unlimited BBQ feast and drinks.',null,'Mad Monkey Boat Party','Unlimited hostel BBQ & drinks'),
('indonesia',9,9,'Day 9','Gili Trawangan → Kuta Lombok','Dive into the crystal-clear waters on the "Monkey See, Monkey Do" Snorkeling Trip (10:30 AM to 4:00 PM) to spot tropical marine life. Afterwards, take a short boat transfer to mainland Lombok followed by a shuttle to Mad Monkey Kuta Lombok.','Boat & shuttle to Kuta Lombok','"Monkey See, Monkey Do" Snorkeling Trip',null),
('indonesia',10,12,'Days 10–12','Kuta Lombok Surf Camp','Welcome to Surf Camp! Over the next three days, eat breakfast, then hit the waves around 9:00 to 10:00 AM. You''ll head to different beaches each day depending on where the swell is best. Head back for lunch and a video analysis session with your instructors to review your form (and watch yourself wipe out in slow motion). Catch another afternoon surf session before diving into nightly events at the hostel. Rinse and repeat!',null,'3-Day Surf Camp (daily surf sessions, video breakdown, beach transfers)','Daily breakfast, family dinner + 2 drinks per day'),
('indonesia',13,13,'Day 13','Kuta Lombok','Say farewell to your group of newfound friends as your Indonesian adventure comes to an end. Catch a quick 30-minute shuttle transfer to Lombok Airport (LOP) for your onward flight.','Departure shuttle to Lombok Airport (LOP)',null,null),
('indonesia-7',1,1,'Day 1','Gili Trawangan','Welcome to Gili T! Arrive on the island, shake off the travel day with an ice-cold beer, and dive straight into the pool to cool off. Check into Mad Monkey Gili T, explore the beach, or hang out at the hostel before joining the crew for a traditional Mexican family dinner and drinks.',null,'Welcome drink & pool chill','Mexican family dinner (plus 2 free drinks)'),
('indonesia-7',2,2,'Day 2','Gili Trawangan','Enjoy a chill morning to relax and explore the island at your own pace. Head back to Mad Monkey in the afternoon as the energy turns up for an epic Pool Party featuring a live DJ set.',null,'Mad Monkey Foam Party with live DJ',null),
('indonesia-7',3,3,'Day 3','Gili Trawangan','Set sail for the iconic Mad Monkey Boat Party (2:00 PM – 6:00 PM). Dance, swim, and soak up the tropical vibes out on the water. Keep the night going back at the hostel with an unlimited BBQ feast and drinks.',null,'Mad Monkey Boat Party','Unlimited hostel BBQ & drinks'),
('indonesia-7',4,4,'Day 4','Gili Trawangan → Kuta Lombok','Dive into the turquoise ocean on the “Monkey See, Monkey Do” Snorkeling Trip (10:30 AM – 4:00 PM) to spot local marine life. Afterward, take a short boat transfer to mainland Lombok followed by a shuttle to Mad Monkey Kuta Lombok.','Boat & shuttle transfer to Kuta Lombok','“Monkey See, Monkey Do” Snorkeling Trip','Lunch'),
('indonesia-7',5,5,'Day 5','Kuta Lombok (Surf Camp Day 1)','Welcome to Surf Camp! Meet your instructors for a welcome session, get fitted for your gear, receive your welcome pack, and practice your pop-ups on land. Cover surf theory, grab lunch with the crew, and regroup at the hostel tonight for a family dinner and karaoke.',null,'Surf camp intro session (pop-up practice & theory breakdown), nightly hostel karaoke','Breakfast, lunch, family dinner'),
('indonesia-7',6,6,'Day 6','Kuta Lombok (Surf Camp Day 2)','Option to start your morning with a social run club before fueling up with breakfast. Then hit the ocean for a morning surf session at local beaches selected for the day''s best conditions. Head back to the hostel for lunch and a photo/video analysis session with your instructors to break down your technique.',null,'Morning surf session, photo & video analysis, optional morning run club','Breakfast, lunch'),
('indonesia-7',7,7,'Day 7','Kuta Lombok (Surf Camp Day 3)','Fuel up with breakfast before heading out for your final morning surf session on the water. Return to the hostel for lunch, then spend a laid-back afternoon hanging out by the pool with drinks during the Mad Monkey Pool Party.',null,'Morning surf session, Mad Monkey afternoon pool party','Breakfast, lunch'),
('indonesia-7',8,8,'Day 8','Departure day','Say farewell to your crew! Catch a shuttle transfer to Lombok Airport (LOP) for your onward flight.','Shuttle transfer to Lombok Airport (LOP)',null,null),
('laos',1,1,'Day 1','Luang Prabang','Check in to Mad Monkey Luang Prabang, roam the Old Town, riverside cafés or the pool, then dinner at the night market.',null,null,null),
('laos',2,2,'Day 2','Luang Prabang','Kuang Si Falls. Optional sunrise alms giving and Mount Phousi, then the Kuang Si Waterfall tour with lunch included. Night market after.',null,null,'Lunch'),
('laos',3,3,'Day 3','Luang Prabang','Culture day. Stories of Luang Prabang culture tour: the National Museum, UXO Centre and Royal Palace, then jewellery making at the Garden of Eden.',null,null,null),
('laos',4,4,'Day 4','Luang Prabang → Nong Khiaw','Mountain camp. Road trip north to Nong Khiaw, a local museum and a mountain viewpoint hike, then camp out on the mountain top.','Minivan',null,null),
('laos',5,5,'Day 5','Nong Khiaw → Muang Ngoi','River boats. Boat to a Khmu village and waterfall, then upriver to car-free Muang Ngoi for a viewpoint climb and a homestay village dinner.','River boat',null,null),
('laos',6,6,'Day 6','Muang Ngoi → Luang Prabang','Bowling. Head back to Mad Monkey Luang Prabang for night market eats and a bowling night with the crew.','Transfer back to Luang Prabang',null,null),
('laos',7,7,'Day 7','Luang Prabang → Vang Vieng','Paramotor. High-speed train to Vang Vieng (about 55 min), a sunset tandem paramotor flight over the karsts, then the pub crawl.','High-speed train, about 55 min',null,null),
('laos',8,8,'Day 8','Vang Vieng','Blue Lagoons. Full-day tour: Nam Xay viewpoint, Blue Lagoons 1, 2 and 3, Nang Far Cave and kayaking, with lunch. Riverside sunset bars after.',null,null,'Lunch'),
('laos',9,9,'Day 9','Vang Vieng','Tubing. Zipline and the Phakai viewpoint, tipsy tubing on the Nam Song, then a farewell night out with the crew.',null,null,null),
('laos',10,10,'Day 10','Vang Vieng','One last swim, check out and onward travel.',null,null,null),
('thailand',1,1,'Day 1','Bangkok','Welcome to Thailand! Drop your bags at Mad Monkey Bangkok from 2pm, grab the afternoon to chill by the pool or dive straight into the city, then meet your crew at 8pm for Beats + Bingo to kick things off properly.',null,'Check-in from 2pm, free afternoon, Beats + Bingo from 8pm',null),
('thailand',2,2,'Day 2','Bangkok','Time to see the real Bangkok. Wind through the Old Town''s markets, temples and canals from 2pm, then wash the day off on the legendary Bangkok Pub Crawl with your new travel family.',null,'Old Town Bangkok tour (markets, temples & canals), Bangkok Pub Crawl 8pm to 1am',null),
('thailand',3,3,'Day 3','Bangkok → Chiang Mai','A proper lie-in and a lazy day by the pool before the adventure heads north. At 5pm the overnight bus rolls out from Mad Monkey Bangkok: sleep on wheels and wake up in the mountains.','Overnight bus to Chiang Mai, departs 5pm','Free daytime',null),
('thailand',4,4,'Day 4','Chiang Mai','Morning arrival in laid-back Chiang Mai around 9am. Nap it off or hit the pool, then bring the energy for the Mad Monkey Day Party and BBQ dinner from 4pm before the Ultimate Pub Crawl takes over at 10pm.',null,'Mad Monkey Day Party, Chiang Mai Ultimate Pub Crawl','BBQ dinner'),
('thailand',5,5,'Day 5','Chiang Mai','Cliff jumps and floating all afternoon at the Grand Canyon Water Park, then back to base for the Mad Monkey Ultimate Game Night. Expect chaos, laughs and a few new legends.',null,'Grand Canyon Water Park 1pm to 6pm, Ultimate Game Night',null),
('thailand',6,6,'Day 6','Chiang Mai','The big one. Depart at 8am to meet the elephants at an ethical sanctuary, tuck into lunch, then raft the river on bamboo before heading back for karaoke and a mini pub crawl to round it off.','Pick-up 8am','Elephant sanctuary, bamboo rafting, karaoke + mini pub crawl','Lunch'),
('thailand',7,7,'Day 7','Chiang Mai → Pai','The famous 762-bend minivan ride up to Pai, worth every turn. Check in to Mad Monkey Pai around 3:30pm, then chase the sunset at Pai Canyon or Two Huts before an easy night on the pub quiz.','Minivan to Pai, departs 12:30pm','Sunset trip to Pai Canyon or Two Huts, pub quiz',null),
('thailand',8,8,'Day 8','Pai','Grab a rubber ring and float the afternoon away on the tipsy tubing session, Pai''s finest way to spend a day, then keep it rolling with a karaoke night back at base.',null,'Tipsy tubing 12:30pm to 6:30pm, karaoke night',null),
('thailand',9,9,'Day 9','Pai','Go underground on the Lod Cave day tour: bamboo rafts, towering caverns and thousands of swifts at dusk, before Pai''s pub crawl sends the night the right way.',null,'Lod Cave day tour 12pm to 6pm, Pai Pub Crawl',null),
('thailand',10,10,'Day 10','Pai → Chiang Mai','Wind back down the mountain to Chiang Mai with a free afternoon to relax or squeeze in some last exploring, then send the trip off in style at Bar Olympics + karaoke from 8pm.','Minivan, time set by the Pai crew','Free afternoon, Bar Olympics + karaoke',null),
('thailand',11,11,'Day 11','Chiang Mai','All good things... Check out by 11am and carry on: back to Bangkok, on to Hanoi, or wherever''s next. Not sure where to head? Have a chat with the team and we''ll help you plan the next leg.',null,null,null),
('vietnam',1,1,'Day 1','Hanoi','Welcome to Vietnam! Touch down in historic Hanoi, check into the hostel, and enjoy some free time to settle in. Tonight, kick things off with a welcome drink at the hostel to meet your crew. End the night with optional free karaoke and a pub crawl.',null,'Welcome drinks, Hanoi street food & bia hoi night',null),
('vietnam',2,2,'Day 2','Hanoi','Get to know the chaotic charm of Hanoi on a guided walking tour led by the local team. Stroll around Hoan Kiem Lake, marvel at St. Joseph''s Cathedral, and cap off the tour watching trains squeeze past on iconic Train Street. (Vietnamese coffee tasting — optional add-on). Tonight, jump into a music quiz before taking on the local nightlife.',null,'Guided Hanoi walking tour (Hoan Kiem Lake, St. Joseph''s Cathedral, Train Street, Vietnamese coffee tasting (optional add-on))','Breakfast'),
('vietnam',3,3,'Day 3','Hanoi → Lan Ha Bay','Depart Hanoi early and transfer to the stunning waters of Lan Ha Bay. Board your cruise boat for an action-packed afternoon of swimming, tubing, and beach volleyball. As the sun sets over the limestone karsts, turn up the music for a boat party before spending the night sleeping under the stars on board.','Transfer to Lan Ha Bay','Lan Ha Bay overnight cruise, swimming, tubing, beach volleyball, sunset boat party','Breakfast, lunch, dinner'),
('vietnam',4,4,'Day 4','Lan Ha Bay → Hanoi','Wake up on the water, grab some breakfast, and hit the bay for a morning kayaking session among hidden lagoons. After a local lunch, cruise back to shore and transfer back to Hanoi. Put on your freshest outfit for the legendary White Party, featuring two hours of free-flowing beer and live DJs, before keeping the night going on Beer Street.','Transfer back to Hanoi','Morning kayaking, Mad Monkey White Party (2-hour free-flow beer & live DJs)','Breakfast, lunch'),
('vietnam',5,5,'Day 5','Hanoi → Ha Giang','Enjoy a relaxed day in Hanoi before making the journey north toward Ha Giang. Arrive, check in, and get prepped for the mountain ride of a lifetime. Get a solid night''s sleep — the epic Ha Giang Loop adventure officially kicks off first thing tomorrow morning!',null,null,'Breakfast'),
('vietnam',6,6,'Day 6','Ha Giang Loop (Day 1)','Wake up in Ha Giang, rally your crew, and ride straight up into the mountains. Day 1 delivers your first taste of loop energy: dramatic panoramic views, winding mountain passes, hidden waterfalls, and crisp high-altitude air. Settle into a local homestay for the night.',null,'Ha Giang Loop riding (mountain passes & hidden waterfalls), homestay experience','Breakfast, lunch, dinner'),
('vietnam',7,7,'Day 7','Ha Giang Loop (Day 2)','This is the day everyone talks about long after the trip ends. Carve through bigger mountains, tackle wilder twisty roads, and conquer the legendary Ma Pi Leng Pass. Stop to soak in the jaw-dropping views of the Nho Que River far below before wrapping up another electric night in the mountains.',null,'Ma Pi Leng Pass ride, Nho Que River viewpoints, mountain homestay','Breakfast, lunch, dinner'),
('vietnam',8,8,'Day 8','Ha Giang Loop (Day 3)','Blend culture, history, and unreal scenery today as you ride up toward Vietnam''s northernmost frontier. Explore ancient ethnic villages, ride deep into remote mountain territory, and spend another unforgettable evening eating, drinking, and laughing with your homestay hosts.',null,'Northern frontier & ancient village exploration, homestay dinner & drinks','Breakfast, lunch, dinner'),
('vietnam',9,9,'Day 9','Ha Giang Loop → Hanoi','Take on the final stretch of the loop! Soak in one last morning of mountain air as you navigate hidden roads, jungle-covered passes, and secret waterfall spots back toward Ha Giang. Say goodbye to the bikes and transfer back to Hanoi with a crew that now feels like family.','Transfer back to Hanoi','Jungle passes & secret waterfalls ride','Breakfast, lunch'),
('vietnam',10,10,'Day 10','Hanoi → Ninh Binh → sleeper bus','Trade city streets for breathtaking countryside on a full-day tour to Ninh Binh. Known as “Ha Long Bay on Land”, you''ll glide past towering karst peaks and through emerald caves on a traditional sampan boat in Tam Coc. After dinner, board a VIP cabin sleeper bus for an overnight journey south to Hoi An.','VIP cabin sleeper bus to Hoi An','Full-day Ninh Binh tour, Tam Coc sampan boat ride','Breakfast, lunch'),
('vietnam',11,11,'Day 11','Hoi An','Roll into coastal Hoi An early, check into the hostel, and spend the morning relaxing pool-side. Around 4:00 PM, the party starts! Dive into the Mad Monkey Sunset Pool Party with free beer, happy hour cocktails, and an all-you-can-eat backyard BBQ spread.',null,'Mad Monkey Sunset Pool Party','All-you-can-eat backyard BBQ dinner (plus free beer)'),
('vietnam',12,12,'Day 12','Hoi An','Hop on two wheels at 11:00 AM for a cycling tour around Hoi An. Get creative at a traditional lantern workshop, drop by the Rehahn Gallery & Museum, walk across the iconic Japanese Covered Bridge, explore an ancient house, and visit a world-famous local tailor. Cap off the ride back at the hostel with an ice-cold beer, then hit free karaoke and a pub crawl tonight.',null,'Guided Hoi An cycling tour (lantern workshop, Rehahn Gallery, Japanese Bridge, ancient house, tailor stop)','Breakfast, lunch'),
('vietnam',13,13,'Day 13','Hoi An','Out early for a classic Hoi An experience! Explore a bustling local market before paddling through coconut mangroves in a traditional bamboo basket boat. Next, roll up your sleeves for a hands-on cooking class with a local chef to learn delicacies like bánh xèo and spring rolls. End the day with a relaxing sunset river cruise before your final big night out.',null,'Local market tour, coconut mangrove bamboo basket boat ride, hands-on Vietnamese cooking class, sunset river cruise','Breakfast, cooking class lunch'),
('vietnam',14,14,'Day 14','Hoi An','Enjoy one last breakfast with your crew and swap contacts before checking out. Head to Da Nang Airport (DAD) for your onward flight home or to your next destination.',null,null,'Breakfast'),
('vietnam-7',1,1,'Day 1','Hanoi','Welcome to Vietnam! Touch down in historic Hanoi, check into the hostel, and enjoy some free time to settle in. Tonight, kick things off with a welcome drink at the hostel to meet your crew. End the night with optional free karaoke and a pub crawl.',null,'Welcome drinks, Hanoi street food & bia hoi night',null),
('vietnam-7',2,2,'Day 2','Hanoi','Get to know the dynamic energy of Hanoi on a guided walking tour led by the local team. Stroll around Hoan Kiem Lake, marvel at St. Joseph''s Cathedral, and finish up watching trains squeeze down famous Train Street. (Vietnamese coffee tasting — optional add-on). Tonight, test your trivia skills with a music quiz before hitting the nightlife.',null,'Guided Hanoi walking tour (Hoan Kiem Lake, St. Joseph''s Cathedral, Train Street, Vietnamese coffee tasting (optional add-on))','Breakfast'),
('vietnam-7',3,3,'Day 3','Hanoi → Ha Giang','Enjoy an easy-going day in Hanoi before making the journey north toward Ha Giang. Arrive, check in, and get your gear ready for the ride ahead. Rest up tonight — the official 4-day Ha Giang Loop adventure starts first thing tomorrow morning!',null,null,'Breakfast'),
('vietnam-7',4,4,'Day 4','Ha Giang Loop (Day 1)','Wake up in Ha Giang, rally your crew, and ride straight up into the mountains. Day 1 is all about high-altitude energy: sweeping views, twisting passes, hidden waterfalls, and crisp mountain air. Settle into your first local homestay tonight.',null,'Ha Giang Loop riding (mountain passes & hidden waterfalls), homestay experience','Breakfast, lunch, dinner'),
('vietnam-7',5,5,'Day 5','Ha Giang Loop (Day 2)','This is the ride you''ll be talking about long after you head home. Conquer bigger peaks, tackle wild winding roads, and ride the legendary Ma Pi Leng Pass. Stop for panoramic viewpoints over the valley before wrapping up another epic evening in the mountains.',null,'Ma Pi Leng Pass ride, panoramic mountain viewpoints, local homestay','Breakfast, lunch, dinner'),
('vietnam-7',6,6,'Day 6','Ha Giang Loop (Day 3)','Blend culture, history, and unreal scenery as you head toward Vietnam''s northern frontier. Explore ancient villages, ride deep into remote mountain landscapes, and spend another unforgettable evening sharing meals and drinks with your homestay hosts.',null,'Northern frontier & ancient village exploration, homestay dinner & drinks','Breakfast, lunch, dinner'),
('vietnam-7',7,7,'Day 7','Ha Giang Loop → Hanoi','Take on the final stretch of the loop! Ride through hidden roads, jungle-covered passes, and secret waterfall spots back toward Ha Giang. Say goodbye to the bikes and catch a shuttle transfer back to Hanoi with a crew that now feels like family.','Transfer back to Hanoi','Jungle passes & secret waterfalls ride','Breakfast, lunch'),
('vietnam-7',8,8,'Day 8','Departure day','Wake up in Hanoi and enjoy one last breakfast together with the group. Say your farewells before heading home, or talk to the team about extending your trip south to Ninh Binh and Hoi An!',null,null,'Breakfast');
