-- ALL IN day-by-day for allin_trip_days, generated from mm-squad-trips tools/export-itineraries.ts.
-- Replaces each exported trip's days in one go (a trip whose day count changed loses its old extra days).
begin;
delete from public.allin_trip_days where trip_slug in ('cambodia','indonesia','indonesia-7','laos','thailand','vietnam','vietnam-7');
commit;
